pub fn ts_bodied_arrow_sample_parameter_tokens(layout: Rc<Vec<Rc<ProducedDeclParamSegment>>>, binding: std::string::String, type_ref_token_class: std::string::String) -> Rc<Vec<Rc<ConcreteSyntaxToken>>> {
    crate::std_algebra::fold_list(layout, Rc::new(vec![]), |acc, segment| crate::std_algebra::list_append(acc, match (*segment.clone()).clone() {
    ProducedDeclParamSegment::ProducedParamFixed { token_class: token_class, .. } => Rc::new(vec![Rc::new(ConcreteSyntaxToken::FixedToken {
    token_class: token_class.clone(),
})]),
    ProducedDeclParamSegment::ProducedParamName { token_class: token_class, .. } => Rc::new(vec![Rc::new(ConcreteSyntaxToken::BoundToken {
    token_class: token_class.clone(),
    binding: binding.clone(),
})]),
    ProducedDeclParamSegment::ProducedParamType => Rc::new(vec![Rc::new(ConcreteSyntaxToken::FixedToken {
    token_class: type_ref_token_class.clone(),
})]),
}))
}

pub fn ts_bodied_arrow_sample_params_tokens(rows: Rc<ProducedDeclRenderRows>) -> Rc<Vec<Rc<ConcreteSyntaxToken>>> {
    {
        let first = ts_bodied_arrow_sample_parameter_tokens(rows.param_layout.clone(), "ts_binding_param_x".to_string(), rows.type_ref_token_class.clone());
let separator = crate::std_algebra::fold_list(rows.param_separator.clone(), Rc::new(vec![]), |acc, token_class| crate::std_algebra::list_snoc_item(acc, Rc::new(ConcreteSyntaxToken::FixedToken {
    token_class: token_class.clone(),
})));
let second = ts_bodied_arrow_sample_parameter_tokens(rows.param_layout.clone(), "ts_binding_param_y".to_string(), rows.type_ref_token_class.clone());
crate::std_algebra::list_append(first, crate::std_algebra::list_append(separator, second))
}
}

