#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum TsGramBuild1State {
    TsGramBuild1StateInit,
    TsGramBuild1StateReady {
        expr: Rc<GrammarExpr>,
    },
}
impl TsGramBuild1State {
    pub fn expr(&self) -> Rc<GrammarExpr> {
        match self {
            TsGramBuild1State::TsGramBuild1StateInit => panic!("no expr on unit variant"),
            TsGramBuild1State::TsGramBuild1StateReady { expr: __val, .. } => __val.clone(),
        }
    }
}

pub fn ts_grammar_sequence_from_token_classes() -> Rc<GrammarExpr> {
    match (*crate::std_algebra::fold_list(ts_canonical_add_fn_tokens(), Rc::new(TsGramBuild1State::TsGramBuild1StateInit), |state, token| match (*state.clone()).clone() {
    TsGramBuild1State::TsGramBuild1StateInit => Rc::new(TsGramBuild1State::TsGramBuild1StateReady {
    expr: ts_grammar_terminal(crate::v2_std_compilers_target_model::concrete_syntax_token_class(token.clone())),
}),
    TsGramBuild1State::TsGramBuild1StateReady { expr: acc, .. } => Rc::new(TsGramBuild1State::TsGramBuild1StateReady {
    expr: Rc::new(GrammarExpr::Sequence {
    left: acc.clone(),
    right: ts_grammar_terminal(crate::v2_std_compilers_target_model::concrete_syntax_token_class(token.clone())),
}),
}),
})).clone() {
    TsGramBuild1State::TsGramBuild1StateInit => ts_grammar_terminal("ts_token_kw_function".to_string()),
    TsGramBuild1State::TsGramBuild1StateReady { expr: result, .. } => result.clone(),
}
}

