pub fn ts_lex() -> Rc<LexRules> {
    Rc::new(LexRules::ModeledLexRules {
    root: ts_lex_rules(),
})
}

pub fn ts_lex_token_class_membership() -> Rc<HashMap<Symbol, bool>> {
    thread_local! {
        static CACHED: Rc<HashMap<Symbol, bool>> = {
            crate::v2_std_compilers_lexing::lex_rule_set_token_class_map(ts_lex_rules())
        };
    }
    CACHED.with(|c: &Rc<HashMap<Symbol, bool>>| c.clone())
}

pub fn ts_lex_token_symbol(sym: std::string::String) -> bool {
    crate::std_algebra::map_contains_key(ts_lex_token_class_membership(), sym)
}

pub fn ts_formal_grammar_symbol_from_token(token: Rc<ConcreteSyntaxToken>) -> Rc<FormalGrammarSymbol> {
    match (*token.clone()).clone() {
    ConcreteSyntaxToken::FixedToken { token_class: c, .. } => crate::v2_std_grammar::grammar_formal_terminal(c.clone()),
    ConcreteSyntaxToken::BoundToken { token_class: c, binding: b, .. } => crate::v2_std_grammar::grammar_formal_terminal_bound(c.clone(), b.clone()),
}
}

pub fn ts_formal_rhs_from_tokens(tokens: Rc<Vec<Rc<ConcreteSyntaxToken>>>) -> Rc<Vec<Rc<FormalGrammarSymbol>>> {
    crate::std_algebra::fold_list(tokens, Rc::new(vec![]), |acc, token| crate::std_algebra::list_snoc_item(acc, ts_formal_grammar_symbol_from_token(token)))
}

pub fn ts_formal_production_fn_add() -> Rc<FormalProduction> {
    crate::v2_std_grammar::grammar_formal_production("ts_production_fn_add".to_string(), ts_formal_rhs_from_tokens(ts_canonical_add_fn_tokens()))
}

