pub fn ts_build_per_language_fact_bundle_registry() -> Rc<Outcome<Rc<PerLanguageFactBundleRegistry>>> {
    {
        let target = ts_g14_grounding_target_model();
let number_subject = ts_number_facts_node(ts_facts_number());
let bigint_subject = ts_bigint_facts_node(ts_facts_bigint());
let bool_subject = ts_bool_facts_node(ts_facts_boolean());
let string_subject = ts_string_facts_node(ts_facts_string());
match (*ts_insert_per_language_primitive_axis(crate::v2_std_grounding::empty_per_language_fact_bundle_registry(), number_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisSurfaceSpelling {}, ts_inhabitant_atom(ts_facts_number().surface_spelling.clone()))).clone() {
    Outcome::Accepted { value: r0, .. } => match (*ts_insert_per_language_primitive_axis(r0.clone(), number_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisWidth {}, ts_inhabitant_atom("ts_tag_bits64".to_string()))).clone() {
    Outcome::Accepted { value: r1, .. } => match (*ts_insert_per_language_primitive_axis(r1.clone(), number_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisEncoding {}, ts_inhabitant_atom(ts_facts_number().ieee754_binary.clone()))).clone() {
    Outcome::Accepted { value: r2, .. } => match (*ts_insert_per_language_primitive_axis(r2.clone(), bigint_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisSurfaceSpelling {}, ts_inhabitant_atom(ts_facts_bigint().surface_spelling.clone()))).clone() {
    Outcome::Accepted { value: r3, .. } => match (*ts_insert_per_language_primitive_axis(r3.clone(), bigint_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisEncoding {}, ts_inhabitant_atom(ts_facts_bigint().encoding.clone()))).clone() {
    Outcome::Accepted { value: r4, .. } => match (*ts_insert_per_language_primitive_axis(r4.clone(), bool_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisSurfaceSpelling {}, ts_inhabitant_atom(ts_facts_boolean().surface_spelling.clone()))).clone() {
    Outcome::Accepted { value: r5, .. } => match (*ts_insert_per_language_primitive_axis(r5.clone(), bool_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisEncoding {}, ts_inhabitant_atom(ts_facts_boolean().encoding.clone()))).clone() {
    Outcome::Accepted { value: r6, .. } => match (*ts_insert_per_language_primitive_axis(r6.clone(), string_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisSurfaceSpelling {}, ts_inhabitant_atom(ts_facts_string().surface_spelling.clone()))).clone() {
    Outcome::Accepted { value: r7, .. } => ts_insert_per_language_primitive_axis(r7.clone(), string_subject.clone(), target.clone(), ModelCorePrimitiveFactAxis::ModelCoreFactAxisEncoding {}, ts_inhabitant_atom(ts_facts_string().encoding.clone())),
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
},
    Outcome::Rejected { diagnostics: d, .. } => Rc::new(Outcome::Rejected {
    diagnostics: d.clone(),
}),
}
}
}

